    "id": "eb31890f-945d-41ef-a280-65859ab8a471",
    "code": "G-08",
    "title": "G-08 Endapan Teras Sungai Bengawan Solo Tengger",
    "name": "Endapan Teras Sungai Bengawan Solo Tengger",
    "slug": "g-08-endapan-teras-sungai-bengawan-solo-tengger",
    "category": "Keragaman Geologi",
