    "id": "8764c1f4-a787-4e01-af2b-cd4bdb5f09e2",
    "code": "G-13",
    "title": "G-13 Kompleks Goa Sumberarum",
    "name": "Kompleks Goa Sumberarum",
    "slug": "g-13-kompleks-goa-sumberarum",
    "category": "Keragaman Geologi",
